#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_partners__IPv4_ && fail 'an IP group named fws_partners__IPv4_ exists; nothing was written'
named FW_GROUP_IP fws_bogons && fail 'an IP group named fws_bogons exists; nothing was written'
named FW_GROUP_IP fws_www.example.com && fail 'an IP group named fws_www.example.com exists; nothing was written'
named FW_GROUP_PORT fws_tcp-0-1023_2049-65535 && fail 'a port group named fws_tcp-0-1023_2049-65535 exists; nothing was written'
named FW_GROUP_PORT fws_tcp-0-24_26-65535 && fail 'a port group named fws_tcp-0-24_26-65535 exists; nothing was written'
named FW_GROUP_IP fws_line_69_src && fail 'an IP group named fws_line_69_src exists; nothing was written'
named FW_GROUP_IP fws_line_69.2_src && fail 'an IP group named fws_line_69.2_src exists; nothing was written'
named FW_GROUP_PORT fws_tcp-80_443 && fail 'a port group named fws_tcp-80_443 exists; nothing was written'
named FW_GROUP_IP fws_line_57_dst && fail 'an IP group named fws_line_57_dst exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_partners__IPv4_ --set .COMMENT 'FWShift: partners (IPv4)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_bogons --set .COMMENT 'FWShift: bogons'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0/8
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 127.0.0.0/8
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 169.254.0.0/16
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 240.0.0.0/4
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_www.example.com --set .COMMENT 'FWShift: www.example.com'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP www.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_line_69_src --set .COMMENT 'FWShift: not 10.10.5.10'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-10.10.5.9
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.11-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_line_69.2_src --set .COMMENT 'FWShift: not 10.10.5.11'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-10.10.5.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.12-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_line_57_dst --set .COMMENT 'FWShift: 10.20.1.10, 203.0.113.10'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.1.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.10
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-0-1023_2049-65535 --set .COMMENT 'FWShift: tcp-0-1023,2049-65535'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 0-1023
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 2049-65535
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-0-24_26-65535 --set .COMMENT 'FWShift: tcp-0-24,26-65535'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 0-24
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 26-65535
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-80_443 --set .COMMENT 'FWShift: tcp-80,443'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'bogons: pf line 47: block in quick from <bogons> label "bogons"'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_bogons
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'line 46: pf line 46: block all'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF all --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'bogons: pf line 47: block in quick from <bogons> label "bogons"'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_bogons
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'line 46: pf line 46: block all'
N=$((N+1))
gc --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
